	new cjs.ButtonHelper(this.backInfo, 0, 1, 2);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.entryBarrierButton}]}).to({state:[{t:this.internationalGrowth}]},1).to({state:[{t:this.backInfo}]},1).wait(1));

	// TEXT
